    const meetsOf = (i: number): [boolean, boolean] => (i < 2 ? [sides[2][0], sides[3][0]] : [sides[0][0], sides[1][0]]);
    const INF = shared.ctx.gutterInfo || (shared.ctx.gutterInfo = { gutters: [], downpipes: [], drains: [] });
