    for (let k = -6; k <= 6; k++) bx('metal', x + k * (gh / 6.5) - 0.006, top + 0.005, z - gh + 0.004, x + k * (gh / 6.5) + 0.006, top + 0.011, z + gh - 0.004, 0x6a6e72);
